function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawBackground(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#5bb6e8');sky.addColorStop(.52,'#a4d8ec');sky.addColorStop(1,'#e1f1f0');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant dreamy sun
let sun=ctx.createRadialGradient(W*.76,H*.2,6,W*.76,H*.2,130);sun.addColorStop(0,'#fff6d8dd');sun.addColorStop(.25,'#fff1c977');sun.addColorStop(1,'#fff1c900');ctx.fillStyle=sun;ctx.fillRect(W*.76-140,H*.2-140,280,280);
// layered hills and clouds
for(let layer=0;layer<3;layer++){let base=H*(.51+layer*.075),offset=-(cam*(.10+layer*.08))%310;ctx.fillStyle=['#86cce0','#acdce6','#d1e9e9'][layer];ctx.beginPath();ctx.moveTo(0,H);for(let x=-330+offset;x<W+350;x+=310){let peak=base-60-layer*8;ctx.quadraticCurveTo(x+95,peak-60,x+175,base);ctx.quadraticCurveTo(x+240,base+22,x+310,base-15)}ctx.lineTo(W,H);ctx.closePath();ctx.fill()}
for(const c of decor){let x=(c.x-cam*c.speed)%(W+200);if(x< -100)x+=W+200;ctx.globalAlpha=c.alpha;cloud(x,c.y,c.r)}ctx.globalAlpha=1;
// floating tiny islands in deep background
for(let i=0;i<9;i++){let x=(i*263-cam*.25)%(W+200);if(x< -100)x+=W+200;let y=H*.65+(i*53%90);ctx.fillStyle='#709eb555';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+60,y);ctx.lineTo(x+48,y+20);ctx.lineTo(x+20,y+33);ctx.lineTo(x+9,y+19);ctx.closePath();ctx.fill()}}
function cloud(x,y,r){ctx.beginPath();ctx.arc(x,y,r*.58,0,Math.PI*2);ctx.arc(x+r*.48,y-r*.25,r*.65,0,Math.PI*2);ctx.arc(x+r,y,r*.48,0,Math.PI*2);ctx.arc(x+r*.48,y+r*.13,r*.62,0,Math.PI*2);ctx.fillStyle='#f8fdff';ctx.fill()}
function drawPlatform(p){const x=p.x-cam,y=p.y;if(x+p.w< -20||x>W+20)return;ctx.save();ctx.shadowColor='#224c7570';ctx.shadowBlur=15;ctx.shadowOffsetY=9;let color=p.type==='finish'?'#8265dc':p.type==='check'?'#4cbb9d':'#2984ad';roundRect(x,y,p.w,p.h,7,color);ctx.shadowBlur=0;ctx.shadowOffsetY=0;roundRect(x,y,p.w,8,4,p.type==='finish'?'#b49aff':p.type==='check'?'#87e7c5':'#63d5e5');ctx.fillStyle='#ffffff20';for(let i=12;i<p.w-10;i+=28){ctx.fillRect(x+i,y+12,12,2)}ctx.fillStyle='#183d5a55';for(let i=14;i<p.w-8;i+=40){ctx.fillRect(x+i,y+16,4,4)}
// chunky island underside
ctx.beginPath();ctx.moveTo(x+3,y+p.h);ctx.lineTo(x+p.w-3,y+p.h);ctx.lineTo(x+p.w-12,y+p.h+13);ctx.lineTo(x+p.w*.72,y+p.h+19);ctx.lineTo(x+p.w*.34,y+p.h+13);ctx.lineTo(x+11,y+p.h+18);ctx.closePath();ctx.fillStyle='#276a87';ctx.fill();if(p.type==='check'){ctx.fillStyle='#d2fff1';ctx.font='10px sans-serif';ctx.fillText('✦',x+p.w/2-3,y-9)}if(p.type==='finish')drawPortal(x+p.w-45,y-1);ctx.restore()}
function drawPortal(x,y){let pulse=1+Math.sin(elapsed*4)*.06;ctx.save();ctx.translate(x,y-48);ctx.scale(pulse,pulse);ctx.shadowColor='#a795ff';ctx.shadowBlur=28;ctx.strokeStyle='#c9b8ff';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(20,25,20,29,0,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=10;ctx.strokeStyle='#80eaff';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(20,25,12,22,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#eff4ff';ctx.font='15px sans-serif';ctx.fillText('✦',13,31);ctx.restore()}
function drawCoin(c){if(c.got)return;let y=c.y+Math.sin(elapsed*3+c.phase)*4,x=c.x-cam;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(elapsed*2+c.phase)*.18);ctx.shadowColor='#ffd54c';ctx.shadowBlur=14;ctx.fillStyle='#ffce4d';ctx.beginPath();ctx.arc(0,0,c.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff0a1';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#fff4bf';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',0,1);ctx.restore()}
function drawHazard(h){let x=h.x-cam;ctx.save();ctx.shadowColor='#ff5a8266';ctx.shadowBlur=12;roundRect(x,h.y,h.w,h.h,5,'#fa6584','#ffd0d9');ctx.shadowBlur=0;ctx.fillStyle='#653a70';ctx.beginPath();ctx.arc(x+9,h.y+8,2,0,Math.PI*2);ctx.arc(x+21,h.y+8,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#653a70';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+11,h.y+14);ctx.lineTo(x+19,h.y+14);ctx.stroke();ctx.restore()}
