// shadow
ctx.fillStyle='#235b7860';ctx.beginPath();ctx.ellipse(0,player.h/2+3,17,5,0,0,Math.PI*2);ctx.fill();
// legs and shoes
ctx.fillStyle='#344c9b';roundRect(-12,7,10,17+(ground?Math.max(0,run):0),3,'#334c9b');roundRect(3,7,10,17-(ground?Math.max(0,run):0),3,'#334c9b');roundRect(-14,20,14,7,3,'#f5f8ff');roundRect(1,20,14,7,3,'#f5f8ff');
// torso
roundRect(-15,-8,30,22,6,'#29aee2');roundRect(-15,-8,30,5,3,'#70e1f3');
// arm
ctx.fillStyle='#ffce9d';roundRect(-20,-6,7,19,3,'#ffcb94');roundRect(13,-6,7,19,3,'#ffcb94');
// head
roundRect(-14,-27,28,24,7,'#ffd3a4');ctx.fillStyle='#493525';ctx.beginPath();ctx.arc(-5,-16,1.8,0,Math.PI*2);ctx.arc(6,-16,1.8,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#9c563b';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(1,-11,4,0,.8);ctx.stroke();
// blue cap
ctx.fillStyle='#4056c7';ctx.beginPath();ctx.roundRect(-15,-32,30,10,5);ctx.fill();ctx.fillStyle='#6b83ff';ctx.beginPath();ctx.ellipse(2,-22,13,3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffdc64';ctx.fillRect(-3,-29,6,3);ctx.restore()}
function render(){ctx.clearRect(0,0,W,H);drawBackground();platforms.forEach(drawPlatform);coins.forEach(drawCoin);hazards.forEach(drawHazard);drawPlayer();
// subtle vignette
let vg=ctx.createLinearGradient(0,0,0,H);vg.addColorStop(0,'#0c285922');vg.addColorStop(.2,'transparent');vg.addColorStop(.83,'transparent');vg.addColorStop(1,'#16355620');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H)}
function loop(t){if(!started||over)return;const dt=Math.min(.035,(t-last)/1000||.016);last=t;update(dt);render();requestAnimationFrame(loop)}
function idle(){render();if(!started)requestAnimationFrame(idle)}
addEventListener('resize',()=>{resize();render()});resize();player.y=platforms[0].y-player.h;render();requestAnimationFrame(idle);
})();
</script>
