function loseLife(){if(player.invuln>0)return;lives--;ui.lives.textContent=lives;beep(170,.25);if(lives<=0){over=true;started=false;ui.title.innerHTML='OH NO,<br><em>YOU FELL!</em>';ui.message.textContent=`You collected ${coinTotal} stars. The sky islands aren't going anywhere—give it another go!`;ui.play.textContent='TRY AGAIN  ↻';ui.play.onclick=()=>{reset();ui.title.innerHTML='READY,<br><em>ROOKIE?</em>';ui.message.textContent='Run, leap, and collect stars across the clouds. Reach the glowing portal without taking a dip!';ui.play.textContent="LET'S PLAY  →";begin()};ui.modal.classList.remove('hidden');return}player.x=player.checkpoint;let cp=platforms.find(p=>p.type==='check'&&p.x<=player.checkpoint);player.y=cp?cp.y-player.h:platforms[0].y-player.h;player.vx=player.vy=0;player.invuln=1.5;showToast('Checkpoint saved. Try again!')}
